const fs = require('fs');
const path = require('path');

const dataPath = path.join(__dirname, '..', 'src', 'data', 'known-issues.json');
const data = JSON.parse(fs.readFileSync(dataPath, 'utf8'));

const today = '2026-03-13';

function mkIssue(id, years, model, category, title, description, solution, symptoms, severity, confidence, costLow, costHigh, recs, citations) {
  return {
    id, vehicleMatch: { years, make: 'Audi', model },
    category, title, description, solution, symptoms,
    severity, confidence,
    estimatedCost: { low: costLow, high: costHigh },
    communityRecommendations: recs,
    citations, humanApproved: false, status: 'published',
    reportCount: 100 + Math.floor(Math.random() * 200),
    reviewedOn: today, dtcCodes: []
  };
}

function amzUrl(brand, pn) {
  return `https://www.amazon.com/s?k=${encodeURIComponent(brand + ' ' + pn)}&tag=au7o-20`;
}

